import { useFocusVisible } from '@ark-ui/solid';
import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import {
  Menu as MenuPrimitive,
  useMenu,
  useMenuContext,
  useMenuItemContext,
} from '@ark-ui/solid/menu';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { children, splitProps } from 'solid-js';
import { CheckIcon, ChevronDownIcon, ChevronRightIcon } from '@/lib/moduix/icons/ui/Icons';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import styles from './Menu.module.css';

type MenuIndicatorPosition = 'start' | 'end' | 'none';
type MenuItemTone = 'default' | 'destructive';
type MenuItemProps = ComponentProps<typeof MenuPrimitive.Item> & {
  tone?: MenuItemTone;
};
type MenuCheckboxItemProps = ComponentProps<typeof MenuPrimitive.CheckboxItem> & {
  indicator?: MenuIndicatorPosition;
};
type MenuRadioItemProps = ComponentProps<typeof MenuPrimitive.RadioItem> & {
  indicator?: MenuIndicatorPosition;
};
type MenuRootProps = ComponentProps<typeof MenuPrimitive.Root> & OverlayPortalProps;
type MenuRootProviderProps = ComponentProps<typeof MenuPrimitive.RootProvider> & OverlayPortalProps;

function MenuRoot(props: MenuRootProps) {
  const [local, others] = splitProps(props, [
    'children',
    'lazyMount',
    'portalled',
    'portalRef',
    'unmountOnExit',
  ]);

  return (
    <OverlayPortalProvider portalled={local.portalled} portalRef={local.portalRef}>
      <MenuPrimitive.Root
        lazyMount={local.lazyMount ?? true}
        unmountOnExit={local.unmountOnExit ?? true}
        {...others}
      >
        {local.children}
      </MenuPrimitive.Root>
    </OverlayPortalProvider>
  );
}

function MenuRootProvider(props: MenuRootProviderProps) {
  const [local, others] = splitProps(props, [
    'children',
    'lazyMount',
    'portalled',
    'portalRef',
    'unmountOnExit',
  ]);

  return (
    <OverlayPortalProvider portalled={local.portalled} portalRef={local.portalRef}>
      <MenuPrimitive.RootProvider
        lazyMount={local.lazyMount ?? true}
        unmountOnExit={local.unmountOnExit ?? true}
        {...others}
      >
        {local.children}
      </MenuPrimitive.RootProvider>
    </OverlayPortalProvider>
  );
}

function MenuTrigger(props: ComponentProps<typeof MenuPrimitive.Trigger>) {
  const focusVisible = useFocusVisible();
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <MenuPrimitive.Trigger
      asChild={local.asChild}
      data-slot="menu-trigger"
      data-focus-visible={focusVisible() ? '' : undefined}
      class={clsx(!local.asChild && styles.trigger, local.class)}
      {...others}
    />
  );
}

function MenuTriggerIcon(props: ComponentProps<'span'>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <span data-slot="menu-trigger-icon" class={clsx(styles.triggerIcon, local.class)} {...others}>
      {resolvedChildren() ?? <ChevronDownIcon class={styles.iconSvg} />}
    </span>
  );
}

function MenuIndicator(props: ComponentProps<typeof MenuPrimitive.Indicator>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <MenuPrimitive.Indicator
      data-slot="menu-indicator"
      class={clsx(styles.indicator, local.class)}
      {...others}
    >
      {resolvedChildren() ?? <ChevronDownIcon class={styles.iconSvg} />}
    </MenuPrimitive.Indicator>
  );
}

function MenuContextTrigger(props: ComponentProps<typeof MenuPrimitive.ContextTrigger>) {
  const focusVisible = useFocusVisible();
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <MenuPrimitive.ContextTrigger
      asChild={local.asChild}
      data-slot="menu-context-trigger"
      data-focus-visible={focusVisible() ? '' : undefined}
      class={clsx(!local.asChild && styles.contextTrigger, local.class)}
      {...others}
    />
  );
}

function MenuPositioner(props: ComponentProps<typeof MenuPrimitive.Positioner>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <OverlayPortal>
      <MenuPrimitive.Positioner
        data-slot="menu-positioner"
        class={clsx(styles.positioner, local.class)}
        {...others}
      />
    </OverlayPortal>
  );
}

function MenuContent(props: ComponentProps<typeof MenuPrimitive.Content>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);

  return (
    <MenuPrimitive.Content
      asChild={local.asChild}
      data-slot="menu-content"
      class={clsx(styles.content, local.class)}
      {...others}
    >
      {local.children}
    </MenuPrimitive.Content>
  );
}

function MenuViewport(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <ark.div
      asChild={local.asChild}
      data-scope="menu"
      data-part="viewport"
      data-slot="menu-viewport"
      class={clsx(styles.viewport, local.class)}
      {...others}
    />
  );
}

function MenuArrow(props: ComponentProps<typeof MenuPrimitive.Arrow>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <MenuPrimitive.Arrow data-slot="menu-arrow" class={clsx(styles.arrow, local.class)} {...others}>
      {resolvedChildren() ?? <MenuArrowTip />}
    </MenuPrimitive.Arrow>
  );
}

function MenuArrowTip(props: ComponentProps<typeof MenuPrimitive.ArrowTip>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.ArrowTip
      data-slot="menu-arrow-tip"
      class={clsx(styles.arrowTip, local.class)}
      {...others}
    />
  );
}

function MenuItem(props: MenuItemProps) {
  const [local, others] = splitProps(props, ['class', 'tone']);

  return (
    <MenuPrimitive.Item
      data-slot="menu-item"
      data-tone={local.tone ?? 'default'}
      class={clsx(styles.item, local.class)}
      {...others}
    />
  );
}

function MenuTriggerItem(props: ComponentProps<typeof MenuPrimitive.TriggerItem>) {
  const [local, others] = splitProps(props, ['children', 'class']);

  return (
    <MenuPrimitive.TriggerItem
      data-slot="menu-trigger-item"
      class={clsx(styles.triggerItem, local.class)}
      {...others}
    >
      {local.children}
    </MenuPrimitive.TriggerItem>
  );
}

function MenuTriggerItemIcon(props: ComponentProps<'span'>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <span
      data-slot="menu-trigger-item-icon"
      class={clsx(styles.triggerItemIcon, local.class)}
      {...others}
    >
      {resolvedChildren() ?? <ChevronRightIcon class={styles.iconSvg} />}
    </span>
  );
}

function MenuSeparator(props: ComponentProps<typeof MenuPrimitive.Separator>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.Separator
      data-slot="menu-separator"
      class={clsx(styles.separator, local.class)}
      {...others}
    />
  );
}

function MenuItemGroup(props: ComponentProps<typeof MenuPrimitive.ItemGroup>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.ItemGroup
      data-slot="menu-item-group"
      class={clsx(styles.itemGroup, local.class)}
      {...others}
    />
  );
}

function MenuItemGroupLabel(props: ComponentProps<typeof MenuPrimitive.ItemGroupLabel>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.ItemGroupLabel
      data-slot="menu-item-group-label"
      class={clsx(styles.itemGroupLabel, local.class)}
      {...others}
    />
  );
}

function MenuRadioItemGroup(props: ComponentProps<typeof MenuPrimitive.RadioItemGroup>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.RadioItemGroup
      data-slot="menu-radio-item-group"
      class={clsx(styles.radioItemGroup, local.class)}
      {...others}
    />
  );
}

function MenuRadioItem(props: MenuRadioItemProps) {
  const [local, others] = splitProps(props, ['class', 'indicator']);

  return (
    <MenuPrimitive.RadioItem
      data-slot="menu-radio-item"
      data-indicator-position={local.indicator ?? 'start'}
      class={clsx(styles.radioItem, local.class)}
      {...others}
    />
  );
}

function MenuCheckboxItem(props: MenuCheckboxItemProps) {
  const [local, others] = splitProps(props, ['class', 'indicator']);

  return (
    <MenuPrimitive.CheckboxItem
      data-slot="menu-checkbox-item"
      data-indicator-position={local.indicator ?? 'start'}
      class={clsx(styles.checkboxItem, local.class)}
      {...others}
    />
  );
}

function MenuItemIndicator(props: ComponentProps<typeof MenuPrimitive.ItemIndicator>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <MenuPrimitive.ItemIndicator
      data-slot="menu-item-indicator"
      class={clsx(styles.itemIndicator, local.class)}
      {...others}
    >
      {resolvedChildren() ?? <CheckIcon class={styles.itemIndicatorIcon} />}
    </MenuPrimitive.ItemIndicator>
  );
}

function MenuItemText(props: ComponentProps<typeof MenuPrimitive.ItemText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.ItemText
      data-slot="menu-item-text"
      class={clsx(styles.itemText, local.class)}
      {...others}
    />
  );
}

function MenuItemTextContent(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      data-slot="menu-item-text-content"
      class={clsx(styles.itemTextContent, local.class)}
      {...others}
    />
  );
}

function MenuItemTextIcon(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      data-slot="menu-item-text-icon"
      class={clsx(styles.itemTextIcon, local.class)}
      {...others}
    />
  );
}

function MenuItemTextLabel(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      data-slot="menu-item-text-label"
      class={clsx(styles.itemTextLabel, local.class)}
      {...others}
    />
  );
}

function MenuItemShortcut(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      data-slot="menu-item-shortcut"
      class={clsx(styles.itemShortcut, local.class)}
      {...others}
    />
  );
}

const Menu = Object.assign(MenuRoot, {
  Root: MenuRoot,
  RootProvider: MenuRootProvider,
  Context: MenuPrimitive.Context,
  Trigger: MenuTrigger,
  TriggerIcon: MenuTriggerIcon,
  Indicator: MenuIndicator,
  ContextTrigger: MenuContextTrigger,
  Positioner: MenuPositioner,
  Content: MenuContent,
  Viewport: MenuViewport,
  Arrow: MenuArrow,
  ArrowTip: MenuArrowTip,
  Item: MenuItem,
  TriggerItem: MenuTriggerItem,
  TriggerItemIcon: MenuTriggerItemIcon,
  Separator: MenuSeparator,
  ItemGroup: MenuItemGroup,
  ItemGroupLabel: MenuItemGroupLabel,
  RadioItemGroup: MenuRadioItemGroup,
  RadioItem: MenuRadioItem,
  CheckboxItem: MenuCheckboxItem,
  ItemIndicator: MenuItemIndicator,
  ItemText: MenuItemText,
  ItemTextContent: MenuItemTextContent,
  ItemTextIcon: MenuItemTextIcon,
  ItemTextLabel: MenuItemTextLabel,
  ItemShortcut: MenuItemShortcut,
  ItemContext: MenuPrimitive.ItemContext,
});

export { Menu, useMenu, useMenuContext, useMenuItemContext };

@layer moduix.components {
  .trigger,
  .contextTrigger {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-menu-trigger-gap, var(--moduix-spacing-2));
    min-height: var(--moduix-menu-trigger-height, var(--moduix-size-md));
    margin: 0;
    padding: var(--moduix-menu-trigger-padding-y, var(--moduix-spacing-1))
      var(--moduix-menu-trigger-padding-x, var(--moduix-spacing-4));
    border: var(--moduix-menu-trigger-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-menu-trigger-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-menu-trigger-radius, var(--moduix-radius-md));
    background-color: var(--moduix-menu-trigger-bg, var(--moduix-color-background));
    color: var(--moduix-menu-trigger-color, var(--moduix-color-foreground));
    font: inherit;
    font-size: var(--moduix-menu-trigger-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-menu-trigger-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-menu-trigger-line-height, var(--moduix-line-height-text-sm));
    user-select: none;
    outline: 0;
    cursor: pointer;
    transition:
      background-color var(--moduix-menu-transition, var(--moduix-transition-default)),
      border-color var(--moduix-menu-transition, var(--moduix-transition-default)),
      color var(--moduix-menu-transition, var(--moduix-transition-default));

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-menu-trigger-bg-hover);
      }
    }

    &:active {
      background-color: var(--moduix-menu-trigger-bg-active, var(--moduix-menu-trigger-bg-hover));
    }

    &[data-current][data-state='open'] {
      background-color: var(--moduix-menu-trigger-bg-active, var(--moduix-menu-trigger-bg-hover));
    }

    &:focus[data-focus-visible] {
      outline: var(
          --moduix-menu-focus-ring-width,
          var(--moduix-menu-trigger-border-width, var(--moduix-border-width-sm))
        )
        solid var(--moduix-menu-focus-ring-color, var(--moduix-color-ring));
      outline-offset: calc(
        var(
            --moduix-menu-focus-ring-width,
            var(--moduix-menu-trigger-border-width, var(--moduix-border-width-sm))
          ) *
          -1
      );
    }

    &[data-disabled] {
      pointer-events: none;
      opacity: var(--moduix-menu-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .triggerIcon,
  .indicator {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--moduix-menu-trigger-icon-size, var(--moduix-spacing-4));
    height: var(--moduix-menu-trigger-icon-size, var(--moduix-spacing-4));
    flex-shrink: 0;
    color: var(--moduix-menu-trigger-icon-color, currentColor);
  }

  .iconSvg,
  .indicator > svg {
    width: 100%;
    height: 100%;
  }

  .positioner {
    z-index: var(--z-index);
    width: var(--positioner-width, auto);
    max-width: var(--available-width);
    outline: 0;
  }

  .content {
    --arrow-size: var(--moduix-menu-arrow-size, var(--moduix-spacing-2-5));
    --arrow-background: var(--moduix-menu-popup-bg, var(--moduix-color-popover));

    position: relative;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    min-width: min(
      max(var(--reference-width, 0px), var(--moduix-menu-popup-min-width, 12rem)),
      var(--available-width, 100vw)
    );
    max-width: min(var(--moduix-menu-popup-max-width, 20rem), var(--available-width, 100vw));
    overflow: var(--moduix-menu-popup-overflow, visible);
    padding-block: var(
      --moduix-menu-popup-padding-y,
      var(--moduix-popup-list-padding-y, var(--moduix-spacing-1))
    );
    border-radius: var(--moduix-menu-popup-radius, var(--moduix-radius-md));
    background-color: var(--moduix-menu-popup-bg, var(--moduix-color-popover));
    color: var(--moduix-menu-popup-color, var(--moduix-color-popover-foreground));
    outline: var(--moduix-menu-popup-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-menu-popup-border-color, var(--moduix-color-border));
    box-shadow: var(--moduix-menu-popup-shadow, var(--moduix-shadow-lg));
    transform-origin: var(--transform-origin);
    z-index: calc(var(--moduix-z-popup) + var(--layer-index, 0));

    &[data-state='open'] {
      animation: menuContentIn
        var(
          --moduix-menu-transition,
          var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
            var(--moduix-popup-motion-easing, var(--moduix-ease-in-out))
        );
    }

    &[data-state='closed'] {
      animation: menuContentOut
        var(
          --moduix-menu-transition,
          var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
            var(--moduix-popup-motion-easing, var(--moduix-ease-in-out))
        );
    }
  }

  .viewport {
    display: flex;
    max-height: min(var(--moduix-menu-popup-max-height, 24rem), var(--available-height, 100dvh));
    flex-direction: column;
    overflow: auto;
  }

  .arrow {
    --arrow-background: var(--moduix-menu-popup-bg, var(--moduix-color-popover));
  }

  .arrowTip {
    border-block-start: var(--moduix-menu-popup-border-width, var(--moduix-border-width-sm)) solid
      var(
        --moduix-menu-arrow-stroke-color,
        var(--moduix-menu-popup-border-color, var(--moduix-color-border))
      );
    border-inline-start: var(--moduix-menu-popup-border-width, var(--moduix-border-width-sm)) solid
      var(
        --moduix-menu-arrow-stroke-color,
        var(--moduix-menu-popup-border-color, var(--moduix-color-border))
      );
  }

  .item,
  .triggerItem,
  .radioItem,
  .checkboxItem {
    position: relative;
    box-sizing: border-box;
    min-height: var(
      --moduix-menu-item-height,
      var(--moduix-popup-item-min-height, var(--moduix-size-sm))
    );
    margin: 0;
    border: 0;
    border-radius: var(--moduix-menu-item-radius, var(--moduix-radius-sm));
    outline: 0;
    background-color: var(--moduix-menu-item-bg, transparent);
    color: inherit;
    font: inherit;
    font-size: var(
      --moduix-menu-item-font-size,
      var(--moduix-popup-item-font-size, var(--moduix-text-sm))
    );
    line-height: var(
      --moduix-menu-item-line-height,
      var(--moduix-popup-item-line-height, var(--moduix-line-height-text-sm))
    );
    text-decoration: none;
    user-select: none;
    cursor: default;

    &:is([data-highlighted], [data-state='open']) {
      z-index: 0;

      &::before {
        content: '';
        z-index: -1;
        position: absolute;
        inset-block: 0;
        inset-inline: var(
          --moduix-menu-highlight-inset-x,
          var(--moduix-popup-highlight-inset-x, var(--moduix-spacing-1))
        );
        border-radius: var(
          --moduix-menu-highlight-radius,
          var(--moduix-popup-highlight-radius, var(--moduix-radius-sm))
        );
        background-color: var(--moduix-menu-submenu-open-bg, var(--moduix-color-accent));
      }
    }

    &[data-highlighted] {
      color: var(--moduix-menu-highlight-color, var(--moduix-color-accent-foreground));
    }

    &[data-highlighted]::before {
      background-color: var(--moduix-menu-highlight-bg, var(--moduix-color-accent));
    }

    &[data-disabled] {
      pointer-events: none;
      background-color: var(
        --moduix-menu-item-bg-disabled,
        var(--moduix-menu-item-bg, transparent)
      );
      color: var(--moduix-menu-item-disabled-color, var(--moduix-color-muted-foreground));
      cursor: default;
    }

    &[data-tone='destructive'] {
      color: var(--moduix-menu-item-destructive-color, var(--moduix-color-destructive));

      &[data-highlighted] {
        color: var(
          --moduix-menu-item-destructive-highlight-color,
          var(--moduix-menu-item-destructive-color, var(--moduix-color-destructive))
        );

        &::before {
          background-color: var(
            --moduix-menu-item-destructive-highlight-bg,
            color-mix(in oklab, var(--moduix-color-destructive) 12%, transparent)
          );
        }
      }
    }
  }

  .item {
    display: flex;
    align-items: center;
    gap: var(--moduix-menu-item-gap, var(--moduix-spacing-2));
    padding-block: var(
      --moduix-menu-item-padding-y,
      var(--moduix-popup-item-padding-y, var(--moduix-spacing-1))
    );
    padding-inline: var(
        --moduix-menu-item-padding-x-start,
        var(--moduix-popup-item-padding-x-start, var(--moduix-spacing-3))
      )
      var(
        --moduix-menu-item-padding-x-end,
        var(--moduix-popup-item-padding-x-end, var(--moduix-spacing-3))
      );
  }

  .triggerItem {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-menu-trigger-item-gap, var(--moduix-spacing-3));
    padding-block: var(
      --moduix-menu-item-padding-y,
      var(--moduix-popup-item-padding-y, var(--moduix-spacing-1))
    );
    padding-inline: var(
        --moduix-menu-item-padding-x-start,
        var(--moduix-popup-item-padding-x-start, var(--moduix-spacing-3))
      )
      var(--moduix-menu-trigger-item-padding-x-end, var(--moduix-spacing-3));
  }

  .triggerItemIcon {
    box-sizing: border-box;
    display: inline-flex;
    width: var(--moduix-menu-trigger-item-icon-size, var(--moduix-spacing-3-5));
    height: var(--moduix-menu-trigger-item-icon-size, var(--moduix-spacing-3-5));
    flex-shrink: 0;
    color: currentColor;

    &:dir(rtl) {
      transform: scaleX(-1);
    }
  }

  .itemGroup {
    display: grid;
    padding-block: var(--moduix-menu-group-padding-y, 0);
  }

  .itemGroupLabel {
    margin: 0;
    padding-block: var(
      --moduix-menu-group-label-padding-y,
      var(--moduix-popup-group-label-padding-y, var(--moduix-spacing-1))
    );
    padding-inline: var(
        --moduix-menu-group-label-padding-x-start,
        var(--moduix-popup-group-label-padding-x-start, var(--moduix-spacing-2-5))
      )
      var(
        --moduix-menu-group-label-padding-x-end,
        var(--moduix-popup-group-label-padding-x-end, var(--moduix-spacing-3))
      );
    color: var(
      --moduix-menu-group-label-color,
      var(--moduix-popup-group-label-color, var(--moduix-color-muted-foreground))
    );
    font-size: var(
      --moduix-menu-group-label-font-size,
      var(--moduix-popup-group-label-font-size, var(--moduix-text-xs))
    );
    font-weight: var(
      --moduix-menu-group-label-font-weight,
      var(--moduix-popup-group-label-font-weight, var(--moduix-weight-regular))
    );
    line-height: var(
      --moduix-menu-group-label-line-height,
      var(--moduix-popup-group-label-line-height, var(--moduix-line-height-text-xs))
    );
    user-select: none;
    cursor: default;
  }

  .radioItemGroup {
    display: grid;
  }

  .radioItem,
  .checkboxItem {
    display: grid;
    align-items: center;
    gap: var(--moduix-menu-check-gap, var(--moduix-popup-check-gap, var(--moduix-spacing-2)));
    grid-template-columns:
      var(
        --moduix-menu-check-indicator-size,
        var(--moduix-popup-check-indicator-size, var(--moduix-spacing-3))
      )
      minmax(0, 1fr);
    padding-block: var(
      --moduix-menu-item-padding-y,
      var(--moduix-popup-item-padding-y, var(--moduix-spacing-1))
    );
    padding-inline: var(
        --moduix-menu-check-padding-x-start,
        var(--moduix-popup-check-padding-x-start, var(--moduix-spacing-2-5))
      )
      var(
        --moduix-menu-item-padding-x-end,
        var(--moduix-popup-item-padding-x-end, var(--moduix-spacing-3))
      );

    &[data-indicator-position='none'] {
      grid-template-columns: minmax(0, 1fr);
      padding-inline-start: var(
        --moduix-menu-item-padding-x-start,
        var(--moduix-popup-item-padding-x-start, var(--moduix-spacing-3))
      );

      & > .itemIndicator {
        display: none;
      }

      & > .itemText {
        grid-column-start: 1;
      }
    }

    &[data-indicator-position='end'] {
      grid-template-columns:
        minmax(0, 1fr)
        var(
          --moduix-menu-check-indicator-size,
          var(--moduix-popup-check-indicator-size, var(--moduix-spacing-3))
        );

      & > .itemText {
        grid-column-start: 1;
      }

      & > .itemIndicator {
        grid-column-start: 2;
        justify-self: end;
      }
    }
  }

  .checkboxItem[data-state='checked'] {
    > .itemIndicator {
      background-color: var(
        --moduix-menu-checkbox-indicator-bg-checked,
        var(--moduix-menu-checkbox-indicator-bg, transparent)
      );
      border-color: var(
        --moduix-menu-checkbox-indicator-border-color-checked,
        var(--moduix-menu-checkbox-indicator-border-color, currentColor)
      );
    }
  }

  .itemIndicator {
    grid-column-start: 1;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(
      --moduix-menu-check-indicator-size,
      var(--moduix-popup-check-indicator-size, var(--moduix-spacing-3))
    );
    height: var(
      --moduix-menu-check-indicator-size,
      var(--moduix-popup-check-indicator-size, var(--moduix-spacing-3))
    );
    border: var(--moduix-menu-checkbox-indicator-border-width, 0) solid
      var(--moduix-menu-checkbox-indicator-border-color, currentColor);
    border-radius: var(--moduix-menu-checkbox-indicator-radius, var(--moduix-radius-xs));
    background-color: var(--moduix-menu-checkbox-indicator-bg, transparent);

    &[data-state='checked'] {
      color: var(--moduix-menu-item-indicator-color-checked, currentColor);
    }
  }

  .itemIndicatorIcon {
    width: 100%;
    height: 100%;
  }

  .itemText {
    grid-column-start: 2;
    min-width: 0;
    overflow: hidden;
  }

  .itemTextContent {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-menu-item-text-content-gap, var(--moduix-spacing-2));
    max-width: 100%;
    min-width: 0;
    vertical-align: top;
  }

  .itemTextIcon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    width: var(--moduix-menu-item-text-icon-size, var(--moduix-spacing-4));
    height: var(--moduix-menu-item-text-icon-size, var(--moduix-spacing-4));
    color: var(--moduix-menu-item-text-icon-color, currentColor);
  }

  .itemTextLabel {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .itemShortcut {
    margin-inline-start: auto;
    padding-inline-start: var(--moduix-menu-item-shortcut-padding-x-start, var(--moduix-spacing-4));
    color: var(--moduix-menu-item-shortcut-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-menu-item-shortcut-font-size, var(--moduix-text-xs));
    line-height: var(--moduix-menu-item-shortcut-line-height, var(--moduix-line-height-text-xs));
    white-space: nowrap;
  }

  .separator {
    box-sizing: border-box;
    height: var(--moduix-menu-separator-height, var(--moduix-border-width-sm));
    margin-block: var(
      --moduix-menu-separator-margin-y,
      var(--moduix-popup-separator-margin-y, var(--moduix-spacing-1-5))
    );
    margin-inline: var(
        --moduix-menu-separator-margin-x-start,
        var(--moduix-popup-separator-margin-x-start, var(--moduix-spacing-3))
      )
      var(
        --moduix-menu-separator-margin-x-end,
        var(--moduix-popup-separator-margin-x-end, var(--moduix-spacing-3))
      );
    border: 0;
    background-color: var(--moduix-menu-separator-color, var(--moduix-color-border));
  }

  @media (prefers-reduced-motion: reduce) {
    .trigger,
    .contextTrigger {
      transition: none;
    }

    .content[data-state] {
      animation: none;
    }
  }

  @keyframes menuContentIn {
    from {
      opacity: var(
        --moduix-menu-popup-starting-opacity,
        var(--moduix-popup-motion-starting-opacity, 0)
      );
      translate: var(
          --moduix-menu-popup-starting-translate-x,
          var(--moduix-popup-motion-starting-translate-x, 0)
        )
        var(
          --moduix-menu-popup-starting-translate-y,
          var(--moduix-popup-motion-starting-translate-y, 0)
        );
      transform: scale(
        var(
          --moduix-menu-popup-starting-scale,
          var(--moduix-popup-motion-starting-scale, var(--moduix-scale-popup))
        )
      );
    }

    to {
      opacity: 1;
      translate: 0 0;
      transform: scale(1);
    }
  }

  @keyframes menuContentOut {
    from {
      opacity: 1;
      translate: 0 0;
      transform: scale(1);
    }

    to {
      opacity: var(
        --moduix-menu-popup-ending-opacity,
        var(--moduix-popup-motion-ending-opacity, 0)
      );
      translate: var(
          --moduix-menu-popup-ending-translate-x,
          var(--moduix-popup-motion-ending-translate-x, 0)
        )
        var(
          --moduix-menu-popup-ending-translate-y,
          var(--moduix-popup-motion-ending-translate-y, 0)
        );
      transform: scale(
        var(
          --moduix-menu-popup-ending-scale,
          var(--moduix-popup-motion-ending-scale, var(--moduix-scale-popup))
        )
      );
    }
  }
}
